<script setup>
import {ref,computed} from 'vue';import ToeicScoreSummary from '../Components/ToeicScoreSummary.vue';import {Head,Link,useForm,router} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';import AppModal from '../Components/AppModal.vue';import FormErrors from '../Components/FormErrors.vue';import {useExamContext} from '../exam-context';
const props=defineProps({results:Object,filters:{type:Object,default:()=>({})},exams:{type:Array,default:()=>[]},exam_rounds:{type:Array,default:()=>[]}});const filterExam=ref(props.filters.exam_id||''),filterRound=ref(props.filters.exam_round_id||'');const {base,context}=useExamContext();const selected=ref(null);const form=useForm({scores:{}});function show(result){selected.value=result;form.clearErrors();form.scores=Object.fromEntries(result.questions.filter(question=>(question.kind||'mcq')!=='mcq').map(question=>[question.id,result.manual_scores?.[question.id]??0]));}
const exportUrl=computed(()=>base.value+'/results/export?'+new URLSearchParams(Object.fromEntries(Object.entries({exam_id:filterExam.value,exam_round_id:filterRound.value}).filter(([,value])=>value!==''))).toString());
function filterResults(){router.get(base.value+'/results',{exam_id:filterExam.value,exam_round_id:filterRound.value},{preserveState:true});}
</script>
<template><Head :title="'Kết quả · '+context.name"/><AppLayout><div class="page-heading"><div><h1>Bài làm & kết quả {{context.name}}</h1><p>Trắc nghiệm chấm tự động; tự luận và bài nói được chấm theo điểm tối đa từng câu.</p></div><a :href="exportUrl" class="btn">Xuất Excel kết quả</a></div><div class="card"><form class="filter-row" @submit.prevent="filterResults"><select v-model="filterExam" aria-label="Lọc theo đề thi"><option value="">Tất cả đề thi</option><option v-for="exam in exams" :key="exam.id" :value="exam.id">{{exam.title}}</option></select><select v-model="filterRound" aria-label="Lọc theo khóa thi"><option value="">Tất cả khóa thi</option><option v-for="round in exam_rounds" :key="round.id" :value="round.id">{{round.name}}</option></select><button>Lọc kết quả</button></form><p class="info-copy">Excel chứa toàn bộ kết quả theo bộ lọc đã chọn, gồm cả các trang khác.</p><div class="tablewrap"><table><thead><tr><th>Thí sinh</th><th>Đề</th><th>Lượt</th><th>Trạng thái</th><th>Điểm theo câu</th><th v-if="context.slug==='toeic'">Listening</th><th v-if="context.slug==='toeic'">Reading</th><th v-if="context.slug==='toeic'">Tổng TOEIC</th><th>Thao tác</th></tr></thead><tbody><tr v-for="result in results.data" :key="result.id"><td>{{result.student.name}}<small class="cell-meta">{{result.student.email}}</small></td><td class="table-title">{{result.exam.title}}</td><td>{{result.attempt_number}}</td><td><span class="pill">{{!result.submitted_at?'Đang làm':result.graded_at?'Đã chấm':'Chờ chấm'}}</span></td><td>{{result.total_points??'—'}}</td><td v-if="context.slug==='toeic'"><template v-if="result.listening_result"><strong>{{result.listening_result.scaled!==null?result.listening_result.scaled+' / 495':'Chưa quy đổi'}}</strong><small class="cell-meta">{{result.listening_result.correct}} / {{result.listening_result.total}} câu đúng</small></template><span v-else>—</span></td><td v-if="context.slug==='toeic'"><template v-if="result.reading_result"><strong>{{result.reading_result.scaled!=null?result.reading_result.scaled+' / 495':'Chưa quy đổi'}}</strong><small class="cell-meta">{{result.reading_result.correct}} / {{result.reading_result.total}} câu đúng</small></template><span v-else>—</span></td><td v-if="context.slug==='toeic'"><strong>{{result.toeic_total_score!=null?result.toeic_total_score+' / 990':'—'}}</strong></td><td><button class="secondary" @click="show(result)">Xem / chấm bài</button></td></tr><tr v-if="!results.data.length"><td :colspan="context.slug==='toeic'?9:6" class="empty-state">Chưa có bài làm trong phân hệ này.</td></tr></tbody></table></div><div class="pagination"><Link v-if="results.prev_page_url" :href="results.prev_page_url">← Trước</Link><span>Trang {{results.current_page}} / {{results.last_page}}</span><Link v-if="results.next_page_url" :href="results.next_page_url">Tiếp →</Link></div></div><AppModal :open="!!selected" :title="'Bài làm · '+(selected?.student.name||'')" wide :busy="form.processing" @close="selected=null"><form v-if="selected" @submit.prevent="form.put(base+'/results/'+selected.id,{onSuccess:()=>selected=null})"><FormErrors :errors="form.errors"/><p class="notice">{{selected.exam.title}} · Lượt {{selected.attempt_number}}{{selected.submitted_at?' · Đã nộp':' · Chưa nộp, chưa thể chấm'}}</p><ToeicScoreSummary :listening="selected.listening_result" :reading="selected.reading_result" :total="selected.toeic_total_score"/><section v-for="(question,index) in selected.questions" :key="question.id" class="grade-question"><h2>Câu {{index+1}} · {{question.max_points||1}} điểm</h2><p>{{question.content}}</p><div v-if="(question.kind||'mcq')==='speaking'"><audio v-if="selected.answers?.[question.id]==='recorded'" :src="base+'/results/'+selected.id+'/recordings/'+question.id" controls/><p v-else class="muted">Chưa có bài ghi âm.</p></div><div v-else class="result-answer">{{selected.answers?.[question.id]||'Chưa trả lời'}}</div><p v-if="(question.kind||'mcq')==='mcq'" class="muted">Đáp án đúng: {{question.correct_option}} · {{selected.answers?.[question.id]===question.correct_option?'Đúng':'Sai / chưa trả lời'}}</p><label v-else :for="'score-'+question.id">Điểm chấm<input :id="'score-'+question.id" v-model.number="form.scores[question.id]" type="number" min="0" :max="question.max_points||1" step="0.1" required :disabled="!selected.submitted_at"/></label></section><div class="modal-actions"><button type="button" class="secondary" @click="selected=null">Đóng</button><button v-if="Object.keys(form.scores).length" :disabled="form.processing||!selected.submitted_at">Lưu điểm chấm</button></div></form></AppModal></AppLayout></template>
